"""Verify that the winding number is a genuine group homomorphism.

The winding-number map w sends a loop word to the signed count of the closing
edge (edge 3). This demo checks w(uv) = w(u) + w(v) and w(u^-1) = -w(u) on many
random reduced words, confirming that w : pi_1(hollow) -> Z is a homomorphism.
"""
from __future__ import annotations
import random
from typing import List, Tuple

Letter = Tuple[int, int]
Word = List[Letter]


def free_reduce(word: Word) -> Word:
    stack: Word = []
    for edge, sign in word:
        if stack and stack[-1][0] == edge and stack[-1][1] == -sign:
            stack.pop()
        else:
            stack.append((edge, sign))
    return stack


def free_mul(a: Word, b: Word) -> Word:
    return free_reduce(list(a) + list(b))


def free_inv(word: Word) -> Word:
    return [(e, -s) for e, s in reversed(word)]


def winding_number(word: Word) -> int:
    return sum(s for e, s in word if e == 3)


def random_word(length: int) -> Word:
    return free_reduce([(random.randint(0, 3), random.choice((1, -1)))
                        for _ in range(length)])


def main() -> None:
    random.seed(0)
    ok = True
    for _ in range(10000):
        u = random_word(random.randint(0, 12))
        v = random_word(random.randint(0, 12))
        if winding_number(free_mul(u, v)) != winding_number(u) + winding_number(v):
            ok = False
        if winding_number(free_inv(u)) != -winding_number(u):
            ok = False
    print("homomorphism identities hold on 10000 random pairs:", ok)


if __name__ == "__main__":
    main()

